from collections import defaultdict, deque
import numpy as np

arr = np.array(grid)
rows, cols = arr.shape

def connected_components_color(color):
    """Return list of component sizes for a given color"""
    visited = np.zeros_like(arr, dtype=bool)
    sizes = []

    for r in range(rows):
        for c in range(cols):
            if arr[r, c] == color and not visited[r, c]:
                comp_size = 0
                q = deque([(r, c)])
                visited[r, c] = True
                while q:
                    cr, cc = q.popleft()
                    comp_size += 1
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0<=nr<rows and 0<=nc<cols:
                            if arr[nr, nc] == color and not visited[nr, nc]:
                                visited[nr, nc] = True
                                q.append((nr, nc))
                sizes.append(comp_size)
    return sizes

