# Fill bounding boxes for each color
def fill_bbox_per_color(grid):
    """Fill the bounding box of each color region with that color"""
    rows, cols = len(grid), len(grid[0])

    # Get bounding box for each color
    bbox = {}
    for color in range(10):
        if color == 5:
            continue
        min_r, max_r, min_c, max_c = rows, cols, 0, 0

        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == color:
                    min_r = min(min_r, r)
                    max_r = max(max_r, r)
                    min_c = min(min_c, c)
                    max_c = max(max_c, c)

        if min_r != rows or max_r != cols or min_c != 0 or max_c != cols-1:
            bbox[color] = (min_r, max_r, min_c, max_c)

    # Apply: fill each bbox with corresponding color
    result = [[5]*cols for _ in range(rows)]
    for color, (min_r, max_r, min_c, max_c) in bbox.items():
        for r in range(min_r, max_r+1):
            for c in range(min_c, max_c+1):
                result[r][c] = color

    return result

